// kestrel64-sdk — kgfx microcode driver.
#include <k64/kgfx.h>
#include <k64/rsp.h>
#include <k64/cpu.h>
#include <k64/rdp.h>
#include "kgfx.h"   // generated by k64rsp: KGFX_* DMEM/IMEM offsets

// Microcode image and overlay images, generated from the kgfx sources by k64rsp.
K64_UCODE_DECL(kgfx);
extern const u8 kgfx_ovl[];
_Static_assert(sizeof(k64_kgfx_vcache_t) == 40, "vcache entry layout");
_Static_assert(sizeof(k64_vtx_t) == 16 && sizeof(k64_mtxfx_t) == 64, "kgfx input layout");

// Matrix as integer and fraction halves (s15.16 per entry): the two planes the RSP multiplies.
void k64_mtx_to_fixed(k64_mtxfx_t *out, const k64_mat4_t *m) {
  for (int c = 0; c < 4; c++)
    for (int r = 0; r < 4; r++) {
      s32 v = k64_f2fx16(m->m[c][r]);
      out->i[c][r] = (s16)(v >> 16);
      out->f[c][r] = (u16)v;
    }
}

void k64_viewport_set(k64_viewport_t *vp, u32 w, u32 h) {
  s16 hx = (s16)(w * 2), hy = (s16)(h * 2);   // half extent in s13.2
  // Both halves (two vertices per RSP pass) get the same x/y. z is fixed; w comes from viewport_wnorm.
  for (int i = 0; i < 8; i += 4) {
    vp->scale[i + 0] = hx; vp->scale[i + 1] = (s16)-hy; vp->scale[i + 2] = 0x3FFF; vp->scale[i + 3] = 1;
    vp->trans[i + 0] = hx; vp->trans[i + 1] = hy;       vp->trans[i + 2] = 0x3FFF; vp->trans[i + 3] = 0;
  }
}

void k64_viewport_wnorm(k64_viewport_t *vp, float near, float far) {
  K64_ASSERT(near > 0.f && far > near);
  // W is scaled by K = 2 / (near + far) so the normalised W stays in the fixed-point range.
  s32 k = k64_f2fx16(2.f / (near + far));
  if (k < 1) k = 1;
  for (int i = 3; i < 8; i += 4) {
    vp->scale[i] = (s16)(k >> 16);
    vp->trans[i] = (s16)(u16)k;
  }
}

_Static_assert(sizeof(k64_kgfx_lights_t) == 160, "kgfx light block layout");

// Truncate toward zero and clamp to [lo, hi].
static s32 trunc_clamp(float v, s32 lo, s32 hi) {
  s32 i = (s32)v;
  return i < lo ? lo : i > hi ? hi : i;
}

void k64_kgfx_fog_max(k64_kgfx_list_t *l, s32 start, s32 end, u32 max) {
  K64_ASSERT(0 <= start && start < end && end <= 0x7FFF && 1 <= max && max <= 255);
  u32 k = (u32)(((u64)0x7FFF << 16) / (u32)(end - start));  // 0x7FFF / (end - start), 16.16
  if (k > 0x7FFFFFFF) k = 0x7FFFFFFF;
  // The alpha limit is stored inverted (255 - max).
  k64_kgfx_cmd(l, ((u32)K64_KGFX_OP_FOG << 24) | ((255 - max) << 16) | (k & 0xFFFF),
               ((u32)start << 16) | (k >> 16));
}

// Normal packed as signed 5/6/5 fields (x, y, z), scaled by 15.5 / 31.5 / 15.5 and truncated.
u16 k64_kgfx_pack_normal(float x, float y, float z) {
  s32 nx = trunc_clamp(x * 15.5f, -16, 15), ny = trunc_clamp(y * 31.5f, -32, 31), nz = trunc_clamp(z * 15.5f, -16, 15);
  return (u16)(((nx & 31) << 11) | ((ny & 63) << 5) | (nz & 31));
}

// Multiplier and mask per packed normal field (x, y, z): moves each field into the top bits of a lane.
static void normal_decode(u16 *shift, u16 *mask, int h) {
  shift[h + 0] = 1; shift[h + 1] = 32; shift[h + 2] = 2048; shift[h + 3] = 0;
  mask[h + 0] = 0xF800; mask[h + 1] = 0xFC00; mask[h + 2] = 0xF800; mask[h + 3] = 0;
}

void k64_kgfx_lights_set(k64_kgfx_lights_t *out, const k64_kgfx_light_t *lights, u32 n,
                         u8 amb_r, u8 amb_g, u8 amb_b, const k64_mat4_t *model) {
  K64_ASSERT(n <= K64_KGFX_LIGHTS);
  // The decoded normal is x * 31/32 (5 bits: 15.5 * 2048 / 32768), y * 63/64, z * 31/32;
  // the directions carry the inverse so N . L comes out unscaled.
  static const float undo[3] = { 32.f / 31.f, 64.f / 63.f, 32.f / 31.f };
  // Both halves of each vector (two vertices per pass on the RSP) hold the same values.
  for (u32 i = 0; i < K64_KGFX_LIGHTS; i++) {
    s16 dq[3] = { 0, 0, 0 }, cq[3] = { 0, 0, 0 };
    if (i < n) {
      const k64_kgfx_light_t *li = &lights[i];
      float w[3] = { li->dir.x, li->dir.y, li->dir.z }, d[3];
      for (int k = 0; k < 3; k++)    // model space: transpose of the rotation
        d[k] = model ? model->m[k][0] * w[0] + model->m[k][1] * w[1] + model->m[k][2] * w[2] : w[k];
      float len2 = d[0] * d[0] + d[1] * d[1] + d[2] * d[2];
      float inv = len2 > 0 ? 1.f / k64_sqrtf(len2) : 0;
      const u8 c[3] = { li->r, li->g, li->b };
      for (int k = 0; k < 3; k++) {
        float dk = d[k] * inv;
        dq[k] = (s16)trunc_clamp(dk * undo[k] * 16384.f + (dk < 0 ? -0.5f : 0.5f), -0x7FFF, 0x7FFF);
        cq[k] = (s16)((c[k] * 0x7FFF + 127) / 255);
      }
    }
    for (int h = 0; h < 8; h += 4) {
      for (int k = 0; k < 3; k++) {
        out->dir[k][h + i] = dq[k];
        out->col[i][h + k] = cq[k];
      }
      out->col[i][h + 3] = 0;
    }
  }
  const s16 amb[4] = { (s16)((amb_r * 0x4000 + 127) / 255), (s16)((amb_g * 0x4000 + 127) / 255),
                       (s16)((amb_b * 0x4000 + 127) / 255), 0x4000 };
  for (int h = 0; h < 8; h += 4) {
    for (int k = 0; k < 4; k++) out->amb[h + k] = amb[k];
    normal_decode(out->nshift, out->nmask, h);
  }
}

void k64_kgfx_texgen_set(k64_kgfx_texgen_t *out, const k64_mat4_t *mv, u32 tex_w, u32 tex_h) {
  static const float undo[3] = { 32.f / 31.f, 64.f / 63.f, 32.f / 31.f };
  K64_ASSERT(tex_w <= 512 && tex_h <= 512);
  // view x of a model-space vector v = sum_c mv->m[c][0] * v_c: the axes are the rows
  float ax[2][3];
  for (int a = 0; a < 2; a++) {
    float len2 = 0;
    for (int k = 0; k < 3; k++) { ax[a][k] = mv->m[k][a]; len2 += ax[a][k] * ax[a][k]; }
    float inv = len2 > 0 ? (a ? -1.f : 1.f) / k64_sqrtf(len2) : 0;   // t grows down
    for (int k = 0; k < 3; k++) ax[a][k] *= inv;
  }
  for (int h = 0; h < 8; h += 4) {
    for (int k = 0; k < 3; k++)
      for (int a = 0; a < 4; a++) {
        float d = a < 2 ? ax[a][k] * undo[k] : 0;
        out->dir[k][h + a] = (s16)trunc_clamp(d * 16384.f + (d < 0 ? -0.5f : 0.5f), -0x7FFF, 0x7FFF);
      }
    // st = off + scale * (N . axis) / 2 in s10.5: 0 at -1, the texture size at +1
    out->scale[h + 0] = (s16)(tex_w * 32); out->scale[h + 1] = (s16)(tex_h * 32);
    out->off[h + 0] = (s16)(tex_w * 16);   out->off[h + 1] = (s16)(tex_h * 16);
    out->scale[h + 2] = out->scale[h + 3] = out->off[h + 2] = out->off[h + 3] = 0;
    normal_decode(out->nshift, out->nmask, h);
  }
}

// Starts a kgfx task. The ucode is loaded on first use; otherwise the RSP is halted before its DMEM
// state is rewritten.
static void run(const k64_kgfx_list_t *l, bool intr) {
  if (k64_rsp_loaded != kgfx_text) {
    k64_ucode_t u = K64_UCODE(kgfx);
    k64_rsp_load(&u);
    // overlay sources: VTX is the slot's part of the IMEM image, the others are in kgfx_ovl;
    // the DMA length code goes in the top byte
    #define OVL(n, addr, size) k64_dmem_write(KGFX_OVL_TABLE + 4 * (n), (((size) - 1) >> 3) << 24 | (addr))
    OVL(0, K64_PHYS(kgfx_text) + KGFX_OVL_SLOT, KGFX_OVL_VTX_END - KGFX_OVL_SLOT);
    OVL(1, K64_PHYS(kgfx_ovl) + KGFX_OVL_CLIP_OFF, KGFX_OVL_CLIP_SIZE);
    OVL(2, K64_PHYS(kgfx_ovl) + KGFX_OVL_AUDIO_OFF, KGFX_OVL_AUDIO_SIZE);
    OVL(3, K64_PHYS(kgfx_ovl) + KGFX_OVL_ADPCM_OFF, KGFX_OVL_ADPCM_SIZE);
    OVL(4, K64_PHYS(kgfx_ovl) + KGFX_OVL_PART_OFF, KGFX_OVL_PART_SIZE);
    #undef OVL
  } else {
    SP_STATUS = SP_WR_SET_HALT;
    while (!k64_rsp_halted()) {}
  }
  // The RSP reads the command list from RDRAM: write back the CPU's stores first.
  k64_dcache_writeback(l->base, (u32)((u8 *)l->cur - (u8 *)l->base));
  // Hand the RDP ring (blocks, cursor, end) to the RSP through DMEM.
  k64_rdp_ring_t r;
  k64_rdp_ring_export(&r);
  const u32 *w = (const u32 *)&r;
  for (u32 i = 0; i < sizeof r / 4; i++) k64_dmem_write(KGFX_RING + i * 4, w[i]);
  k64_dmem_write(KGFX_CMDPTR, K64_PHYS(l->base));
  k64_dmem_write(KGFX_FOGDATA + 0, 0);           // fog off: start, K = 0, mask 0xFFFF
  k64_dmem_write(KGFX_FOGDATA + 4, 0x0000FFFFu);
  if (intr) k64_rsp_run_intr(KGFX_START);
  else k64_rsp_run(KGFX_START);
}

void k64_kgfx_run(const k64_kgfx_list_t *l) { run(l, false); }
void k64_kgfx_run_intr(const k64_kgfx_list_t *l) { run(l, true); }

u32 k64_kgfx_wait(void) {
  // A task runs for a few ms. Two seconds without the halt is a hang: show where it stands
  // rather than freeze on the last picture (the only sign on a console).
  u32 t0 = k64_count();
  while (!k64_rsp_wait(4096))
    if (k64_count() - t0 > 2 * K64_COUNT_HZ)
      k64_panic("kgfx: RSP task hung\nSP %08x PC %03x DMA %x\nDPC %08x %08x %08x st %04x",
                (unsigned)SP_STATUS, (unsigned)SP_PC, (unsigned)SP_DMA_BUSY, (unsigned)DPC_START,
                (unsigned)DPC_END, (unsigned)DPC_CURRENT, (unsigned)DPC_STATUS);
  // Take back the RDP ring state the RSP left in DMEM.
  k64_rdp_ring_t r;
  u32 *w = (u32 *)&r;
  for (u32 i = 0; i < sizeof r / 4; i++) w[i] = k64_dmem_read(KGFX_RING + i * 4);
  k64_rdp_ring_import(&r);
  // Primitives from this task may still be sampling TMEM: the next texture load must fence.
  if (k64_dmem_read(KGFX_TRICOUNT) | k64_dmem_read(KGFX_PARTCOUNT))   // may still sample TMEM
    k64_rdps.prim_pending = k64_rdps.tile_pending = k64_rdps.load_pending = true;
  return k64_dmem_read(KGFX_STATUS);
}

u32 k64_kgfx_tri_count(void) { return k64_dmem_read(KGFX_TRICOUNT); }
u32 k64_kgfx_part_count(void) { return k64_dmem_read(KGFX_PARTCOUNT); }

s32 k64_kgfx_particles_scale(const k64_mat4_t *mvp, const k64_viewport_t *vp) {
  // radius in s13.2 = size * |clip x row| * scale_x / W, and the microcode divides by the
  // normalized W' = K * W
  float row = 0;
  for (int c = 0; c < 3; c++) row += mvp->m[c][0] * mvp->m[c][0];
  float k = vp->scale[3] + (u16)vp->trans[3] / 65536.f;
  return k64_f2fx16(k64_sqrtf(row) * (float)vp->scale[0] * k);
}

// Quad (4 vertices) standing on base and turned to face the eye in XZ; s/t are the texture corners.
void k64_kgfx_billboard_y(k64_vtx_t v[4], k64_vec3_t base, float half_w, float height, k64_vec3_t eye,
                          u32 rgba, s16 s0, s16 t0, s16 s1, s16 t1) {
  float dx = eye.x - base.x, dz = eye.z - base.z, d = k64_sqrtf(dx * dx + dz * dz);
  if (d < 1e-6f) { dx = 0; dz = 1; d = 1; }
  dx /= d; dz /= d;
  float rx = dz * half_w, rz = -dx * half_w;   // right as seen from the eye
  // The normal points at the eye, so the billboard is lit as if it faced the camera.
  u16 n = k64_kgfx_pack_normal(dx, 0, dz);
  u8 r = (u8)(rgba >> 24), g = (u8)(rgba >> 16), b = (u8)(rgba >> 8), a = (u8)rgba;
  s16 x0 = (s16)(base.x - rx), z0 = (s16)(base.z - rz), x1 = (s16)(base.x + rx), z1 = (s16)(base.z + rz);
  s16 y0 = (s16)base.y, y1 = (s16)(base.y + height);
  v[0] = (k64_vtx_t){ x0, y0, z0, n, r, g, b, a, s0, t1 };
  v[1] = (k64_vtx_t){ x1, y0, z1, n, r, g, b, a, s1, t1 };
  v[2] = (k64_vtx_t){ x1, y1, z1, n, r, g, b, a, s1, t0 };
  v[3] = (k64_vtx_t){ x0, y1, z0, n, r, g, b, a, s0, t0 };
}

// Copies n vertex-cache entries, starting at first, out of RSP DMEM.
void k64_kgfx_read_vcache(k64_kgfx_vcache_t *out, u32 first, u32 n) {
  K64_ASSERT(first + n <= K64_KGFX_VCACHE + K64_KGFX_CLIP_POOL && ((u32)out & 7) == 0);
  k64_rsp_dma_from(out, KGFX_VCACHE + first * sizeof(k64_kgfx_vcache_t), n * sizeof(k64_kgfx_vcache_t));
}
